#include <bits/stdc++.h>
using namespace std;
#define ll long long

int main() {
    
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
	// your code goes here
	
	int t;
	cin >> t;
	while(t--){
	    
	    int n;
	    cin >> n;
	    
	    vector<ll> a(3 * n);
	    for(int i = 0; i < 3 * n; i++)
	    cin >> a[i];
	    
	    sort(a.rbegin() , a.rend());
	    
	    vector<ll> pref(3 * n + 1 , 0);
	    for(int i = 0; i < 3 * n; i++)
	    pref[i + 1] = pref[i] + a[i];
	    
	    ll mx = -2e18;
	    
	    for(ll k = 0; k <= n; k++){
	        
	        ll lo = 0 , hi = k;
	        
	        while(hi - lo > 2){
	            
	            ll mid1 = lo + (hi - lo) /3;
	            ll mid2 = hi -(hi - lo) / 3;
	            ll val1 = 2 * pref[mid1] + pref[2 * k - mid1] + 3 * pref[3 * n - k - mid1];
	            ll val2 = 2 * pref[mid2] + pref[2 * k - mid2] + 3 * pref[3 * n - k - mid2];
	            
	            if(val1 < val2)
	            lo = mid1;
	            else
	            hi = mid2;
	            
	        }
	        
	        for(ll x = lo; x <= hi; x++){
	            
	            ll val = 2 * pref[x] + pref[2 * k - x] + 3 * pref[3 * n - k - x];
	            mx = max(val , mx);
	        }
	    }
	    
	    cout << mx << '\n';
	}
	return 0;

}
